@page "/"
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@inject NavigationManager Nav

<PageTitle>ShipmentTracker - Home</PageTitle>

<h1>Shipment Tracker</h1>
<p>Welcome to the logistics shipment tracking system.</p>

<AuthorizeView>
    <Authorized>
        <p>You are signed in as <strong>@context.User.Identity?.Name</strong>.</p>
        <div class="d-flex gap-2 mt-3">
            <button class="btn btn-primary" @onclick="GoToShipments">View All Shipments</button>
            <button class="btn btn-outline-primary" @onclick="GoToMyShipments">My Shipments</button>
        </div>
    </Authorized>
    <NotAuthorized>
        <p>Please <a href="Account/Login">log in</a> to manage or track shipments.</p>
        <div class="mt-3">
            <h4>Quick Track</h4>
            <div class="input-group" style="max-width: 400px;">
                <input type="text" class="form-control" placeholder="Enter tracking number" @bind="trackingNumber" @bind:event="oninput" />
                <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
            </div>
            @if (trackedShipment is not null)
            {
                <div class="card mt-3" style="max-width: 400px;">
                    <div class="card-body">
                        <h5 class="card-title">@trackedShipment.TrackingNumber</h5>
                        <p><strong>Status:</strong> @trackedShipment.Status</p>
                        <p><strong>Destination:</strong> @trackedShipment.Destination</p>
                        <p><strong>Estimated Delivery:</strong> @(trackedShipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "N/A")</p>
                    </div>
                </div>
            }
            @if (trackingError)
            {
                <div class="alert alert-warning mt-2" style="max-width: 400px;">Shipment not found.</div>
            }
        </div>
    </NotAuthorized>
</AuthorizeView>

@code {
    private string trackingNumber = string.Empty;
    private ShipmentDto? trackedShipment;
    private bool trackingError;

    private void GoToShipments() => Nav.NavigateTo("shipments");
    private void GoToMyShipments() => Nav.NavigateTo("my-shipments");

    private async Task TrackShipment()
    {
        trackingError = false;
        trackedShipment = null;
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        trackedShipment = await ShipmentService.GetByTrackingNumberAsync(trackingNumber.Trim());
        trackingError = trackedShipment is null;
    }
}

@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>All Shipments</PageTitle>

<h2>Shipments</h2>
<p class="text-muted">Dispatcher view — all shipments with status and destination.</p>

<div class="mb-3">
    <input type="text" class="form-control" style="max-width: 300px;" placeholder="Filter by destination..."
           @bind="filterText" @bind:event="oninput" />
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Shipped</th>
                    <th>Est. Delivery</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadge(s.Status)">@s.Status</span></td>
                        <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                        <td>
                            <select class="form-select form-select-sm" style="width:140px;"
                                    value="@s.Status" @onchange="(e) => ChangeStatus(s, e)">
                                <option value="Pending">Pending</option>
                                <option value="In Transit">In Transit</option>
                                <option value="Out for Delivery">Out for Delivery</option>
                                <option value="Delivered">Delivered</option>
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s => string.IsNullOrEmpty(filterText)
            || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task ChangeStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        var newStatus = e.Value?.ToString() ?? shipment.Status;
        await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
        shipment.Status = newStatus;
    }

    private static string GetStatusBadge(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "In Transit" => "bg-primary",
        "Out for Delivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        _ => "bg-info"
    };
}

