@page "/track"
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2>Track a Shipment</h2>

<div class="mb-3" style="max-width: 500px;">
    <label class="form-label">Tracking Number</label>
    <div class="input-group">
        <input type="text" class="form-control" placeholder="e.g. SHP-001" @bind="trackingNumber" @bind:event="oninput"
               @onkeydown="HandleKeyDown" />
        <button class="btn btn-primary" @onclick="Search" disabled="@searching">
            @if (searching) { <span class="spinner-border spinner-border-sm me-1"></span> }
            Track
        </button>
    </div>
</div>

@if (result is not null)
{
    <div class="card mt-3" style="max-width: 500px;">
        <div class="card-header d-flex justify-content-between">
            <span><strong>@result.TrackingNumber</strong></span>
            <span class="badge @GetStatusBadge(result.Status)">@result.Status</span>
        </div>
        <div class="card-body">
            <p><strong>Origin:</strong> @result.Origin</p>
            <p><strong>Destination:</strong> @result.Destination</p>
            <p><strong>Shipped:</strong> @result.ShippedDate.ToString("MMM dd, yyyy")</p>
            <p class="mb-0"><strong>Estimated Delivery:</strong>
                <span class="text-success fw-bold">@(result.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "Pending")</span>
            </p>
        </div>
    </div>
}
else if (searched && !searching)
{
    <div class="alert alert-warning mt-3" style="max-width: 500px;">
        No shipment found for tracking number "<strong>@searchedNumber</strong>".
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private ShipmentDto? result;
    private bool searching;
    private bool searched;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await Search();
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searching = true;
        searched = false;
        result = null;
        searchedNumber = trackingNumber.Trim();
        result = await ShipmentService.GetByTrackingNumberAsync(searchedNumber);
        searched = true;
        searching = false;
    }

    private static string GetStatusBadge(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "In Transit" => "bg-primary",
        "Out for Delivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        _ => "bg-info"
    };
}

